import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';import 'package:smart_coach_new/core/widgets/custom_button.dart';import 'package:smart_coach_new/core/widgets/custom_checkbox.dart';import 'package:smart_coach_new/core/widgets/field_label_text_view.dart';class CustomMultiSelectField<T, ID> extends StatefulWidget {  final String label;  final bool isRequired;  final String title;  final String hintText;  final List<T> items;  final List<ID> selectedItems;  final ID Function(T item) itemIdBuilder;  final String Function(T item) itemLabelBuilder;  final void Function(List<ID> selectedItems) onSelectionDone;  const CustomMultiSelectField({    super.key,    required this.label,    required this.title,    required this.hintText,    required this.items,    required this.selectedItems,    required this.itemIdBuilder,    required this.itemLabelBuilder,    required this.onSelectionDone,    this.isRequired = false,  });  @override  State<CustomMultiSelectField<T, ID>> createState() =>      _CustomMultiSelectFieldState<T, ID>();}class _CustomMultiSelectFieldState<T, ID>    extends State<CustomMultiSelectField<T, ID>> {  @override  Widget build(BuildContext context) {    List<ID> selected = List<ID>.from(widget.selectedItems);    final selectedLabels = widget.items        .where((item) => selected.contains(widget.itemIdBuilder(item)))        .map(widget.itemLabelBuilder)        .toList();    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        FieldLabelTextView(          labelText: widget.label,          isRequired: widget.isRequired,        ),        SizedBox(height: 1.h),        GestureDetector(          onTap: () {            _showMultiSelectDialog(selected);          },          child: AbsorbPointer(            child: TextFormField(              readOnly: true,              decoration: InputDecoration(                hintText: widget.hintText,                hintStyle: TextStyle(                  fontSize: 12.5.sp,                  fontWeight: FontWeight.normal,                  color: Colors.black,                ),                suffixIcon: Icon(Icons.arrow_drop_down),                contentPadding:                EdgeInsets.symmetric(horizontal: 2.w, vertical: 1.5.h),                border: OutlineInputBorder(                  borderRadius: BorderRadius.circular(2.5.w),                ),                focusedBorder: OutlineInputBorder(                  borderRadius: BorderRadius.circular(2.5.w),                  borderSide:                  BorderSide(color: Colors.grey.shade300, width: 0.4.w),                ),                enabledBorder: OutlineInputBorder(                  borderRadius: BorderRadius.circular(2.5.w),                  borderSide: BorderSide(                    color: Colors.grey.shade300,                    width: 0.4.w,                  ),                ),              ),              controller: TextEditingController(                  text: selectedLabels.isEmpty                      ? 'Select ${widget.label}'                      : selectedLabels.join(', ')),              style: TextStyle(fontSize: 12.5.sp, color: Colors.black),            ),          ),        ),      ],    );  }  void _showMultiSelectDialog(List<ID> selected) async {    FocusScope.of(context).unfocus();    await Future.delayed(Duration(milliseconds: 100));    final tempSelected = List<ID>.from(selected);    showModalBottomSheet(      context: context,      isScrollControlled: true,      shape: RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(2.h)),      ),      builder: (context) => Padding(        padding: EdgeInsets.only(          bottom: MediaQuery.of(context).viewInsets.bottom,          top: 2.h,          left: 4.w,          right: 4.w,        ),        child: LayoutBuilder(builder: (context, constraints) {          final bool shouldScroll = widget.items.length > 6;          final double maxHeight = MediaQuery.of(context).size.height * 0.6;          return Column(            mainAxisSize: MainAxisSize.min,            children: [              Text(widget.title,                  style:                  TextStyle(fontSize: 13.sp, fontWeight: FontWeight.bold)),              SizedBox(height: 1.h),              StatefulBuilder(builder: (context, setModalState) {                final listWidget = widget.items.map((item) {                  final id = widget.itemIdBuilder(item);                  final label = widget.itemLabelBuilder(item);                  final isSelected = tempSelected.contains(id);                  return CustomCheckbox(                    text: label,                    value: isSelected,                    fontSize: 12.5,                    onChange: (checked) {                      setModalState(() {                        if (checked == true) {                          tempSelected.add(id);                        } else {                          tempSelected.remove(id);                        }                      });                    },                  );                }).toList();                return shouldScroll                    ? ConstrainedBox(                  constraints: BoxConstraints(maxHeight: maxHeight),                  child: ListView(                    shrinkWrap: true,                    children: listWidget,                  ),                )                    : Column(                  mainAxisSize: MainAxisSize.min,                  children: listWidget,                );
              }),              SizedBox(height: 2.h),              Row(                mainAxisAlignment: MainAxisAlignment.end,                children: [                  CustomButton(                    text: 'Apply',                    padding:                    EdgeInsets.symmetric(vertical: 1.6.h, horizontal: 5.w),                    textSize: 12,                    radius: 6,                    onPressed: () {                      Navigator.pop(context);                      setState(() => selected = List<ID>.from(tempSelected));                      widget.onSelectionDone(selected);                    },                  ),                ],              ),              SizedBox(height: 2.h),            ],          );        }),      ),    );  }}